            display: flex;
            justify-content: space-between;
            align-items: flex-end;
        }

        .card-expiry {
            font-size: 14px;
        }

        .card-network {
            font-weight: 700;
            font-size: 20px;
        }

        .quick-actions {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 16px;
            margin-top: 32px;
        }

        .action-btn {
            padding: 20px;
            background: var(--card-bg);
            border: 2px solid var(--border);
            border-radius: 12px;
            cursor: pointer;
            transition: all 0.3s;
            text-align: center;
            font-weight: 600;
            color: var(--text-primary);
        }

        .action-btn:hover {
            border-color: var(--primary);
            transform: translateY(-2px);
            box-shadow: var(--shadow);
        }

        .action-btn svg {
            width: 32px;
            height: 32px;
            margin-bottom: 12px;
        }

        .transaction-list {
            max-height: 400px;
            overflow-y: auto;
        }

        .transaction-item {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 16px;
            border-bottom: 1px solid var(--border);
        }

        .transaction-item:last-child {
            border-bottom: none;
        }

        .transaction-info h4 {
            margin-bottom: 4px;
        }

        .transaction-date {
            font-size: 14px;
            color: var(--text-secondary);
        }

        .transaction-amount {
            font-size: 18px;
            font-weight: 600;
        }

        .transaction-amount.positive {
            color: var(--success);
        }

        .transaction-amount.negative {
            color: var(--error);
        }

        .modal {
            display: none;
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.5);
            z-index: 200;
            align-items: center;
            justify-content: center;
        }

        .modal.active {
            display: flex;
        }

        .modal-content {
            background: var(--card-bg);
            padding: 48px;
            border-radius: 16px;
            max-width: 500px;
            width: 90%;
            max-height: 90vh;
            overflow-y: auto;
        }

        .modal-title {
            font-size: 24px;
            font-weight: 700;
            margin-bottom: 24px;
        }

        .modal-close {
            position: absolute;
            top: 16px;
            right: 16px;
            background: none;
            border: none;
            font-size: 24px;
            cursor: pointer;
            color: var(--text-secondary);
        }

        .payment-link-box {
            background: var(--background);
            padding: 16px;
            border-radius: 8px;
            margin: 16px 0;
            word-break: break-all;
            font-family: 'Courier New', monospace;
        }

        .copy-btn {
            margin-top: 12px;
            width: 100%;
            padding: 12px;
            background: var(--secondary);
            color: white;
            border: none;
            border-radius: 8px;
            cursor: pointer;
            font-weight: 600;
        }

        .alert {
            padding: 16px;
            border-radius: 8px;
            margin-bottom: 16px;
        }

        .alert-success {
            background: #D1FAE5;
            color: #065F46;
            border: 1px solid var(--success);
        }

        .alert-error {
            background: #FEE2E2;
            color: #991B1B;
            border: 1px solid var(--error);
        }

        .loading {
            text-align: center;
            padding: 40px;
        }

        .spinner {
            border: 4px solid var(--border);
            border-top: 4px solid var(--primary);
            border-radius: 50%;
            width: 48px;
            height: 48px;
            animation: spin 1s linear infinite;
            margin: 0 auto 16px;
        }

        @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }

        .payment-methods {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 16px;
            margin: 24px 0;
        }

        .payment-method {
            padding: 20px;
            border: 2px solid var(--border);
            border-radius: 12px;
            text-align: center;
            cursor: pointer;
            transition: all 0.3s;
        }

        .payment-method:hover {
            border-color: var(--primary);
            background: var(--background);
        }

        .payment-method.selected {
            border-color: var(--primary);
            background: var(--primary);
            color: white;
        }

        @media (max-width: 768px) {
            .balance-card {
                grid-column: span 1;
            }

            .container {
                padding: 12px;
            }

            .auth-container {
                padding: 32px 24px;
                margin: 40px auto;
            }
        }
    </style>
</head>
<body>
    <!-- Navbar -->
    <nav class="navbar">
        <div class="navbar-content">
            <div class="logo">💰 FinanceApp</div>
            <div class="nav-buttons">
                <button id="nav-login" onclick="showPage('login')">Bejelentkezés</button>
                <button id="nav-register" onclick="showPage('register')">Regisztráció</button>
                <button id="nav-logout" class="btn-logout" style="display: none;" onclick="logout()">Kijelentkezés</button>
            </div>
        </div>
    </nav>

    <div class="container">
        <!-- Login oldal -->
        <div id="login-page" class="page active">
            <div class="auth-container">
                <h1 class="auth-title">Bejelentkezés</h1>
                <div id="login-alert"></div>
                <form onsubmit="handleLogin(event)">
                    <div class="form-group">
                        <label>Email</label>
                        <input type="email" id="login-email" required>
                    </div>
                    <div class="form-group">
                        <label>Jelszó</label>
                        <input type="password" id="login-password" required>
                    </div>
                    <button type="submit" class="btn">Bejelentkezés</button>
                    <button type="button" class="btn btn-secondary" onclick="showPage('register')">
                        Regisztráció
                    </button>
                </form>
            </div>
        </div>

        <!-- Register oldal -->
        <div id="register-page" class="page">
            <div class="auth-container">
                <h1 class="auth-title">Regisztráció</h1>
                <div id="register-alert"></div>
                <form onsubmit="handleRegister(event)">
                    <div class="form-group">
                        <label>Email</label>
                        <input type="email" id="register-email" required>
                    </div>
                    <div class="form-group">
                        <label>Jelszó</label>
                        <input type="password" id="register-password" required minlength="6">
                    </div>
                    <button type="submit" class="btn">Fiók létrehozása</button>
                    <button type="button" class="btn btn-secondary" onclick="showPage('login')">
                        Már van fiókom
                    </button>
                </form>
            </div>
        </div>

        <!-- Dashboard oldal -->
        <div id="dashboard-page" class="page">
            <div class="dashboard-grid">
                <div class="balance-card">
                    <div class="balance-label">Teljes egyenleg</div>
                    <div class="balance-amount" id="total-balance">$0.00</div>
                    <div style="display: flex; gap: 24px; margin-top: 16px;">
                        <div>
                            <div style="opacity: 0.8; font-size: 14px;">Crypto (USD)</div>
                            <div style="font-size: 20px; font-weight: 600;" id="crypto-balance">$0.00</div>
                        </div>
                        <div>
                            <div style="opacity: 0.8; font-size: 14px;">Fiat</div>
                            <div style="font-size: 20px; font-weight: 600;" id="fiat-balance">$0.00</div>
                        </div>
                        <div>
                            <div style="opacity: 0.8; font-size: 14px;">Költhető (kártya)</div>
                            <div style="font-size: 20px; font-weight: 600;" id="card-spending">$0.00</div>
                        </div>
                    </div>
                </div>

                <div class="card">
                    <h3 style="margin-bottom: 24px;">Virtuális kártyám</h3>
                    <div id="card-container">
                        <div class="loading">
                            <div class="spinner"></div>
                            <p>Kártya betöltése...</p>
                        </div>
                    </div>
                </div>

                <div class="card">
                    <h3 style="margin-bottom: 16px;">Tranzakciók</h3>
                    <div id="transactions-list" class="transaction-list">
                        <p style="text-align: center; color: var(--text-secondary); padding: 24px;">
                            Még nincsenek tranzakciók
                        </p>
                    </div>
                </div>
            </div>

            <div class="quick-actions">
                <button class="action-btn" onclick="openModal('payment-link-modal')">
                    <div>💸</div>
                    Fizetési link
                </button>
                <button class="action-btn" onclick="openModal('card-spend-modal')">
                    <div>💳</div>
                    Kártyás költés
                </button>
                <button class="action-btn" onclick="loadBalance()">
                    <div>🔄</div>
                    Egyenleg frissítése
                </button>
            </div>
        </div>

        <!-- Payment page -->
        <div id="payment-page" class="page">
            <div class="auth-container" style="max-width: 600px;">
                <h1 class="auth-title">Fizetés</h1>
                <div id="payment-details-container">
                    <div class="loading">
                        <div class="spinner"></div>
                        <p>Fizetési részletek betöltése...</p>
                    </div>
                </div>
            </div>
        </div>
    </div>

    <!-- Payment Link Modal -->
    <div id="payment-link-modal" class="modal">
        <div class="modal-content" style="position: relative;">
            <button class="modal-close" onclick="closeModal('payment-link-modal')">×</button>
            <h2 class="modal-title">Fizetési link létrehozása</h2>
            <div id="payment-link-alert"></div>
            <form onsubmit="createPaymentLink(event)">
                <div class="form-group">
                    <label>Összeg (USD)</label>
                    <input type="number" id="payment-amount" step="0.01" min="0.01" required>
                </div>
                <div class="form-group">
                    <label>Leírás</label>
                    <input type="text" id="payment-description" required>
                </div>
                <button type="submit" class="btn">Link generálása</button>
            </form>
            <div id="generated-link-container" style="display: none;">
                <h3 style="margin: 24px 0 12px;">Fizetési link:</h3>
                <div class="payment-link-box" id="generated-link"></div>
                <button class="copy-btn" onclick="copyPaymentLink()">Másolás 📋</button>
                <div style="margin-top: 16px; padding: 12px; background: #EEF2FF; border-radius: 8px;">
                    <p style="font-size: 14px;">✅ Támogatott fizetési módok:</p>
                    <p style="font-size: 14px; margin-top: 8px;">🍎 Apple Pay | 📱 Google Pay | 💳 Bankkártya</p>
                </div>
            </div>
        </div>
    </div>

    <!-- Card Spend Modal -->
    <div id="card-spend-modal" class="modal">
        <div class="modal-content" style="position: relative;">
            <button class="modal-close" onclick="closeModal('card-spend-modal')">×</button>
            <h2 class="modal-title">Kártyás vásárlás</h2>
            <div id="card-spend-alert"></div>
            <form onsubmit="simulateCardSpend(event)">
                <div class="form-group">
                    <label>Összeg (USD)</label>
                    <input type="number" id="spend-amount" step="0.01" min="0.01" required>
                </div>
                <div class="form-group">
                    <label>Kereskedő</label>
                    <input type="text" id="spend-merchant" required placeholder="pl. Amazon, Starbucks">
                </div>
                <button type="submit" class="btn">Vásárlás</button>
            </form>
        </div>
    </div>

    <script>
        let currentUser = null;
        let paymentLinkUrl = '';

        // Oldal navigáció
        function showPage(pageName) {
            document.querySelectorAll('.page').forEach(page => {
                page.classList.remove('active');
            });
            document.getElementById(pageName + '-page').classList.add('active');

            // Check if payment page
            if (window.location.pathname.startsWith('/pay/')) {
                const paymentId = window.location.pathname.split('/').pop();
                loadPaymentDetails(paymentId);
            }
        }

        // Login
        async function handleLogin(event) {
            event.preventDefault();
            const email = document.getElementById('login-email').value;
            const password = document.getElementById('login-password').value;

            try {
                const response = await fetch('/api/login', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({email, password})
                });

                const data = await response.json();

                if (response.ok) {
                    currentUser = data;
                    showAlert('login-alert', 'Sikeres bejelentkezés!', 'success');
                    setTimeout(() => {
                        showPage('dashboard');
                        updateNavbar(true);
                        loadDashboard();
                    }, 1000);
                } else {
                    showAlert('login-alert', data.error || 'Hiba történt', 'error');
                }
            } catch (error) {
                showAlert('login-alert', 'Kapcsolódási hiba', 'error');
            }
        }

        // Register
        async function handleRegister(event) {
            event.preventDefault();
            const email = document.getElementById('register-email').value;
            const password = document.getElementById('register-password').value;

            showAlert('register-alert', 'Fiók létrehozása folyamatban...', 'success');

            try {
                const response = await fetch('/api/register', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({email, password})
                });

                const data = await response.json();

                if (response.ok) {
                    currentUser = data;
                    showAlert('register-alert', 'Sikeres regisztráció! Wallet és kártya létrehozva!', 'success');
                    setTimeout(() => {
                        showPage('dashboard');
                        updateNavbar(true);
                        loadDashboard();
                    }, 2000);
                } else {
                    showAlert('register-alert', data.error || 'Hiba történt', 'error');
                }
            } catch (error) {
                showAlert('register-alert', 'Kapcsolódási hiba', 'error');
            }
        }

        // Logout
        async function logout() {
            await fetch('/api/logout', {method: 'POST'});
            currentUser = null;
            updateNavbar(false);
            showPage('login');
        }

        // Dashboard betöltése
        async function loadDashboard() {
            await loadBalance();
            await loadCard();
            await loadTransactions();
        }

        // Balance betöltése
        async function loadBalance() {
            try {
                const response = await fetch('/api/balance');
                const data = await response.json();

                document.getElementById('total-balance').textContent = '$' + data.total_balance.toFixed(2);
                document.getElementById('crypto-balance').textContent = '$' + data.crypto_balance_usd.toFixed(2);
                document.getElementById('fiat-balance').textContent = '$' + data.fiat_balance.toFixed(2);
                document.getElementById('card-spending').textContent = '$' + data.card_spending_power.toFixed(2);
            } catch (error) {
                console.error('Balance loading error:', error);
            }
        }

        // Kártya betöltése
        async function loadCard() {
            try {
                const response = await fetch('/api/card');
                const data = await response.json();

                if (response.ok) {
                    document.getElementById('card-container').innerHTML = `
                        <div class="virtual-card">
                            <div class="card-logo">VIRTUAL CARD</div>
                            <div class="card-number">•••• •••• •••• ${data.last4}</div>
                            <div class="card-details">
                                <div class="card-expiry">
                                    <div style="font-size: 12px; opacity: 0.7;">ÉRVÉNYES</div>
                                    ${data.exp_month}/${data.exp_year}
                                </div>
                                <div class="card-network">${data.network}</div>
                            </div>
                        </div>
                        <div style="margin-top: 16px; text-align: center;">
                            <p style="font-size: 14px; color: var(--text-secondary);">
                                ✅ Apple Pay kompatibilis | ✅ Google Pay kompatibilis
                            </p>
                        </div>
                    `;
                } else {
                    document.getElementById('card-container').innerHTML = `
                        <p style="text-align: center; color: var(--text-secondary);">Kártya még nem került kibocsátásra</p>
                        <button class="btn" style="margin-top: 16px;" onclick="issueCard()">Kártya igénylése</button>
                    `;
                }
            } catch (error) {
                console.error('Card loading error:', error);
            }
        }

        // Tranzakciók betöltése
        async function loadTransactions() {
            try {
                const response = await fetch('/api/transactions');
                const data = await response.json();

                const listEl = document.getElementById('transactions-list');

                if (data.transactions.length === 0) {
                    listEl.innerHTML = '<p style="text-align: center; color: var(--text-secondary); padding: 24px;">Még nincsenek tranzakciók</p>';
                    return;
                }

                listEl.innerHTML = data.transactions.map(tx => `
                    <div class="transaction-item">
                        <div class="transaction-info">
                            <h4>${tx.type === 'card_purchase' ? '💳 ' + tx.merchant : '💰 Beérkezett fizetés'}</h4>
                            <div class="transaction-date">${new Date(tx.timestamp).toLocaleString('hu-HU')}</div>
                        </div>
                        <div class="transaction-amount ${tx.amount > 0 ? 'positive' : 'negative'}">
                            ${tx.amount > 0 ? '+' : ''}$${Math.abs(tx.amount).toFixed(2)}
                        </div>
                    </div>
                `).join('');
            } catch (error) {
                console.error('Transactions loading error:', error);
            }
        }

        // Fizetési link létrehozása
        async function createPaymentLink(event) {
            event.preventDefault();
            const amount = document.getElementById('payment-amount').value;
            const description = document.getElementById('payment-description').value;

            try {
                const response = await fetch('/api/payment-link/create', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({amount, description})
                });

                const data = await response.json();

                if (response.ok) {
                    paymentLinkUrl = data.payment_link;
                    document.getElementById('generated-link').textContent = data.payment_link;
                    document.getElementById('generated-link-container').style.display = 'block';
                    showAlert('payment-link-alert', 'Fizetési link létrehozva!', 'success');
                } else {
                    showAlert('payment-link-alert', data.error || 'Hiba történt', 'error');
                }
            } catch (error) {
                showAlert('payment-link-alert', 'Kapcsolódási hiba', 'error');
            }
        }

        // Kártyás költés szimuláció
        async function simulateCardSpend(event) {
            event.preventDefault();
            const amount = document.getElementById('spend-amount').value;
            const merchant = document.getElementById('spend-merchant').value;

            try {
                const response = await fetch('/api/card/spend', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({amount, merchant})
                });

                const data = await response.json();

                if (response.ok) {
                    showAlert('card-spend-alert', `Sikeres vásárlás! Új egyenleg: $${data.remaining_balance}`, 'success');
                    setTimeout(() => {
                        closeModal('card-spend-modal');
                        loadDashboard();
                    }, 2000);
                } else {
                    showAlert('card-spend-alert', data.error || 'Hiba történt', 'error');
                }
            } catch (error) {
                showAlert('card-spend-alert', 'Kapcsolódási hiba', 'error');
            }
        }

        // Payment details betöltése
        async function loadPaymentDetails(paymentId) {
            try {
                const response = await fetch(`/api/payment-link/${paymentId}`);
                const data = await response.json();

                if (response.ok) {
                    const container = document.getElementById('payment-details-container');
                    container.innerHTML = `
                        <div class="card">
                            <h3>Fizetési részletek</h3>
                            <p style="margin: 16px 0;"><strong>Összeg:</strong> $${data.amount}</p>
                            <p style="margin: 16px 0;"><strong>Leírás:</strong> ${data.description}</p>
                            <div class="payment-methods">
                                <div class="payment-method" onclick="selectPaymentMethod('apple_pay')">
                                    <div style="font-size: 32px;">🍎</div>
                                    <p>Apple Pay</p>
                                </div>
                                <div class="payment-method" onclick="selectPaymentMethod('google_pay')">
                                    <div style="font-size: 32px;">📱</div>
                                    <p>Google Pay</p>
                                </div>
                            </div>
                            <button class="btn" onclick="processPayment('${paymentId}')">Fizetés</button>
                        </div>
                    `;
                }
            } catch (error) {
                console.error('Payment loading error:', error);
            }
        }

        let selectedPaymentMethod = 'apple_pay';

        function selectPaymentMethod(method) {
            selectedPaymentMethod = method;
            document.querySelectorAll('.payment-method').forEach(el => {
                el.classList.remove('selected');
            });
            event.target.closest('.payment-method').classList.add('selected');
        }

        async function processPayment(paymentId) {
            try {
                const response = await fetch(`/api/payment-link/${paymentId}/pay`, {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({payment_method: selectedPaymentMethod})
                });

                const data = await response.json();

                if (response.ok) {
                    alert('✅ Fizetés sikeres! Az összeg pár másodpercen belül jóváírásra kerül.');
                    window.location.href = '/';
                } else {
                    alert('❌ ' + (data.error || 'Hiba történt'));
                }
            } catch (error) {
                alert('❌ Kapcsolódási hiba');
            }
        }

        function copyPaymentLink() {
            navigator.clipboard.writeText(paymentLinkUrl);
            alert('📋 Link másolva!');
        }

        function openModal(modalId) {
            document.getElementById(modalId).classList.add('active');
        }

        function closeModal(modalId) {
            document.getElementById(modalId).classList.remove('active');
        }

        function showAlert(containerId, message, type) {
            const container = document.getElementById(containerId);
            container.innerHTML = `<div class="alert alert-${type}">${message}</div>`;
            setTimeout(() => {
                container.innerHTML = '';
            }, 5000);
        }

        function updateNavbar(loggedIn) {
            document.getElementById('nav-login').style.display = loggedIn ? 'none' : 'inline-block';
            document.getElementById('nav-register').style.display = loggedIn ? 'none' : 'inline-block';
            document.getElementById('nav-logout').style.display = loggedIn ? 'inline-block' : 'none';
        }

        async function issueCard() {
            try {
                const response = await fetch('/api/card/issue', {method: 'POST'});
                const data = await response.json();
                if (response.ok) {
                    alert('✅ Virtuális kártya sikeresen kibocsátva!');
                    loadCard();
                }
            } catch (error) {
                alert('❌ Kártya kibocsátása sikertelen');
            }
        }

        // Init
        window.onload = () => {
            if (window.location.pathname.startsWith('/pay/')) {
                showPage('payment');
            }
        };
    </script>
</body>
</html>
